CREATE TYPE "UserRole" AS ENUM ('ADMIN','BUILDING_OWNER','BUILDING_MANAGER','STORE_OWNER','GUEST');
CREATE TYPE "TenantStatus" AS ENUM ('ACTIVE','SUSPENDED');
CREATE TYPE "ServicePackage" AS ENUM ('FREE','PRO','ENTERPRISE');
CREATE TYPE "BuildingStatus" AS ENUM ('ACTIVE','INACTIVE');
CREATE TYPE "FloorPublishStatus" AS ENUM ('DRAFT','PUBLISHED');
CREATE TYPE "StoreStatus" AS ENUM ('PENDING','ACTIVE','CLOSED');
CREATE TYPE "NodeType" AS ENUM ('NORMAL','DOOR','ELEVATOR','JUNCTION');
CREATE TYPE "EdgeStatus" AS ENUM ('ACTIVE','BLOCKED');
CREATE TYPE "PoiCategory" AS ENUM ('RESTROOM','ELEVATOR','EXIT','INFO','PARKING','CUSTOM');

CREATE TABLE "tenants" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"subdomain" TEXT NOT NULL UNIQUE,"servicePackage" "ServicePackage" NOT NULL DEFAULT 'FREE',"status" "TenantStatus" NOT NULL DEFAULT 'ACTIVE',"archived" BOOLEAN NOT NULL DEFAULT false,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,"deleted_at" TIMESTAMP(3));
CREATE TABLE "users" ("id" TEXT PRIMARY KEY,"tenant_id" TEXT,"email" TEXT NOT NULL UNIQUE,"password_hash" TEXT,"google_id" TEXT UNIQUE,"role" "UserRole" NOT NULL DEFAULT 'GUEST',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,"deleted_at" TIMESTAMP(3),CONSTRAINT "users_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE SET NULL);
CREATE TABLE "refresh_sessions" ("id" TEXT PRIMARY KEY,"user_id" TEXT NOT NULL,"token_hash" TEXT NOT NULL UNIQUE,"expires_at" TIMESTAMP(3) NOT NULL,"revoked_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "refresh_sessions_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE);
CREATE TABLE "buildings" ("id" TEXT PRIMARY KEY,"tenant_id" TEXT NOT NULL,"name" TEXT NOT NULL,"address" TEXT,"status" "BuildingStatus" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,"deleted_at" TIMESTAMP(3),CONSTRAINT "buildings_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id"));
CREATE TABLE "staff_assignments" ("id" TEXT PRIMARY KEY,"user_id" TEXT NOT NULL,"building_id" TEXT NOT NULL,UNIQUE("user_id","building_id"),CONSTRAINT "staff_assignments_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE,CONSTRAINT "staff_assignments_building_id_fkey" FOREIGN KEY ("building_id") REFERENCES "buildings"("id") ON DELETE CASCADE);
CREATE TABLE "floors" ("id" TEXT PRIMARY KEY,"tenant_id" TEXT NOT NULL,"building_id" TEXT NOT NULL,"floor_number" INTEGER NOT NULL,"name" TEXT NOT NULL,"map_image_url" TEXT,"map_width" INTEGER,"map_height" INTEGER,"publish_status" "FloorPublishStatus" NOT NULL DEFAULT 'DRAFT',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,"deleted_at" TIMESTAMP(3),UNIQUE("building_id","floor_number"),CONSTRAINT "floors_building_id_fkey" FOREIGN KEY ("building_id") REFERENCES "buildings"("id"));
CREATE TABLE "nodes" ("id" TEXT PRIMARY KEY,"tenant_id" TEXT NOT NULL,"floor_id" TEXT NOT NULL,"x" DOUBLE PRECISION NOT NULL,"y" DOUBLE PRECISION NOT NULL,"type" "NodeType" NOT NULL DEFAULT 'NORMAL',"accessible" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,"deleted_at" TIMESTAMP(3),CONSTRAINT "nodes_floor_id_fkey" FOREIGN KEY ("floor_id") REFERENCES "floors"("id"));
CREATE TABLE "edges" ("id" TEXT PRIMARY KEY,"tenant_id" TEXT NOT NULL,"floor_id" TEXT NOT NULL,"from_node_id" TEXT NOT NULL,"to_node_id" TEXT NOT NULL,"weight" DOUBLE PRECISION NOT NULL,"accessible" BOOLEAN NOT NULL DEFAULT true,"status" "EdgeStatus" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,"deleted_at" TIMESTAMP(3),CONSTRAINT "edges_floor_id_fkey" FOREIGN KEY ("floor_id") REFERENCES "floors"("id"));
CREATE TABLE "pois" ("id" TEXT PRIMARY KEY,"tenant_id" TEXT NOT NULL,"floor_id" TEXT NOT NULL,"node_id" TEXT NOT NULL,"name" TEXT NOT NULL,"category" "PoiCategory" NOT NULL,"icon" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,"deleted_at" TIMESTAMP(3),CONSTRAINT "pois_floor_id_fkey" FOREIGN KEY ("floor_id") REFERENCES "floors"("id"),CONSTRAINT "pois_node_id_fkey" FOREIGN KEY ("node_id") REFERENCES "nodes"("id"));
CREATE TABLE "stores" ("id" TEXT PRIMARY KEY,"tenant_id" TEXT NOT NULL,"floor_id" TEXT NOT NULL,"node_id" TEXT,"owner_id" TEXT,"name" TEXT NOT NULL,"logo_url" TEXT,"images" TEXT[] NOT NULL,"description" TEXT,"status" "StoreStatus" NOT NULL DEFAULT 'PENDING',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,"deleted_at" TIMESTAMP(3),CONSTRAINT "stores_floor_id_fkey" FOREIGN KEY ("floor_id") REFERENCES "floors"("id"),CONSTRAINT "stores_node_id_fkey" FOREIGN KEY ("node_id") REFERENCES "nodes"("id") ON DELETE SET NULL,CONSTRAINT "stores_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "users"("id") ON DELETE SET NULL);
CREATE TABLE "elevator_links" ("id" TEXT PRIMARY KEY,"tenant_id" TEXT NOT NULL,"building_id" TEXT NOT NULL,"node_id_from" TEXT NOT NULL,"node_id_to" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "elevator_links_building_id_fkey" FOREIGN KEY ("building_id") REFERENCES "buildings"("id"));

CREATE INDEX "users_tenant_id_role_idx" ON "users"("tenant_id","role");
CREATE INDEX "refresh_sessions_user_id_expires_at_idx" ON "refresh_sessions"("user_id","expires_at");
CREATE INDEX "buildings_tenant_id_deleted_at_idx" ON "buildings"("tenant_id","deleted_at");
CREATE INDEX "floors_tenant_id_building_id_deleted_at_idx" ON "floors"("tenant_id","building_id","deleted_at");
CREATE INDEX "nodes_tenant_id_floor_id_deleted_at_idx" ON "nodes"("tenant_id","floor_id","deleted_at");
CREATE INDEX "edges_tenant_id_floor_id_deleted_at_idx" ON "edges"("tenant_id","floor_id","deleted_at");
CREATE INDEX "pois_tenant_id_floor_id_deleted_at_idx" ON "pois"("tenant_id","floor_id","deleted_at");
CREATE INDEX "stores_tenant_id_floor_id_deleted_at_idx" ON "stores"("tenant_id","floor_id","deleted_at");
